INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-black-friday-online-13-billion-adobe', 'black-friday-2026-online-sales-13-billion-adobe-salesforce-cyber-monday-forecast', 'newsroom', 'news_story', 'business', 'EDITORIAL_REVIEW', 0, 'Black Friday online spending tops $9.7 billion by evening, on pace for more than $13 billion, Adobe says', 'Shoppers kept spending despite inflation and high gas prices on Friday, Nov. 27, according to Adobe Analytics data reported by Reuters.', 'Americans spent $9.7 billion online on Black Friday through 6:30 p.m. Eastern on Friday, Nov. 27, up 12.8% from a year earlier, according to Adobe Analytics figures reported by Reuters.

Adobe expects the full-day total to land between $13.0 billion and $13.4 billion, above its September forecast of $12.9 billion, Reuters said. The data showed bargain hunters spending despite inflation and high gas prices, according to the report.

## The rest of the weekend

Adobe forecast $6.1 billion in online sales for Saturday, Nov. 28, up 6%, and $6.4 billion for Sunday, Nov. 29, up 7.5%, Reuters reported. Cyber Monday, Nov. 30, is expected to remain the season''s biggest online shopping day at $15.1 billion, up 6.2%.

Across the five days from Thanksgiving through Cyber Monday, Adobe projects online spending of $47.5 billion, up 7.4%, according to the report. The company expects holiday online spending growth this year to be similar to last year''s.

## A second tracker

Salesforce counted $5.9 billion in U.S. online sales in the first half of Black Friday and $30.7 billion worldwide, Reuters reported. Salesforce projects U.S. Black Friday online spending of $18.7 billion, up 4%, and $83 billion globally, up 5.2%. The two firms measure sales differently, so their totals are not directly comparable.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/DCUSA.Gallery10.TargetBlackFriday.Wikipedia.jpg', 'Black Friday shoppers at a Target store in the DC USA shopping center, Washington (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 7, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261128-black-friday-online-13-billion-adobe-src1', 'bd-20261128-black-friday-online-13-billion-adobe', 'US Black Friday online sales to cross $13 billion, Adobe says', 'https://wmbdradio.com/2026/11/27/us-black-friday-online-sales-to-cross-13-billion-adobe-says/', 'Reuters via WMBD', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-28T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-28. Editor to confirm.', 'newsroom-assistant', '2026-11-28T11:00:00.000Z');
