INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-hawks-edge-celtics-87-86-nba-cup', 'hawks-beat-celtics-87-86-nba-cup-group-c-queta-22-rebounds-celtics-wild-card-detroit', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Hawks edge Celtics 87-86 to win NBA Cup group; Boston advances as wild card to face Detroit', 'Boston blew a 17-point lead and committed a season-high 26 turnovers on Friday, Nov. 27, despite Neemias Queta''s career-high 22 rebounds.', 'The Atlanta Hawks rallied past the Celtics 87-86 in Boston on Friday, Nov. 27, taking first place in East Group C of the NBA Cup, according to Celtics.com and NBC Sports Boston.

Boston led 51-39 at halftime and by as many as 17 points before Atlanta won the third quarter 31-18, NBC Sports Boston reported. Derrick White tied the game late with two free throws and a driving floater, but Nickeil Alexander-Walker put the Hawks back in front with a layup with 54 seconds left and then made two free throws. White''s 3-pointer at the buzzer only cut the final margin to one.

## Turnovers and rebounds

The Celtics turned the ball over 26 times, a season high and 12 more than Atlanta, according to the team''s recap. Jayson Tatum scored 20 points with five assists and four steals, but 16 of his points came in the first half. Queta grabbed a career-high 22 rebounds, the most by a Celtic since Al Jefferson in January 2007, and added 11 points and two blocks, the recap said. Jalen Johnson led Atlanta with 24 points and 12 rebounds.

Both teams made 11 3-pointers and shot under 30% from deep. Coach Joe Mazzulla took the blame for the turnovers, according to the recap.

## What comes next

Boston finished 3-1 in group play and still advanced as the East wild card on a tiebreaker, NBA.com reported. Instead of hosting a quarterfinal, the Celtics will play at Detroit on Saturday, Dec. 5. Atlanta hosts Philadelphia on Friday, Dec. 4.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/6/6a/TD_Garden_(crop).JPG', 'TD Garden, home of the Celtics, in Boston (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 8, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
