INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-leafs-beat-bruins-3-1-pastrnak-injured', 'maple-leafs-beat-bruins-3-1-black-friday-david-pastrnak-lower-body-injury-rielly-100th-goal', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Maple Leafs beat Bruins 3-1 on Black Friday as David Pastrnak leaves with lower-body injury', 'Morgan Rielly scored twice, including his 100th career goal, at TD Garden on Friday, Nov. 27, Boston Hockey Now reported.', 'The Toronto Maple Leafs beat the Bruins 3-1 in the Black Friday matinee at TD Garden on Friday, Nov. 27, and Boston lost captain David Pastrnak to an injury in the first period, according to Boston Hockey Now.

Pastrnak looked uncomfortable after a defensive-zone faceoff, went straight to the bench and then down the tunnel after what appeared to be a non-contact injury, Boston Hockey Now reported. The Bruins said he had a lower-body injury and was unlikely to return. The team had not given a further update when the recap was published.

## How the goals came

Casey Mittelstadt gave Boston a 1-0 lead on a power play at 6:31 of the first period, his ninth goal, with assists from Mason Lohrei and Matt Poitras, according to Boston Hockey Now. Morgan Rielly tied it late in the first on a screened point shot and later scored again for his 100th career goal. Colton Sissons added the insurance goal at 7:24 of the third, set up by Gavin McKenna.

Jeremy Swayman made 15 saves in his second straight loss. Boston also came up empty on a 5-on-3 power play that lasted 1:58, the outlet said.

## Where things stand

The loss was Boston''s fifth in its last six home games and left the Bruins at 15-9-1, Boston Hockey Now reported. Toronto improved to 10-14-3. The Bruins host the Vancouver Canucks at 5 p.m. on Sunday, Nov. 29.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/5/57/2010_winter_classic_pregame.jpg', 'Pregame ceremonies before the Bruins played the 2010 NHL Winter Classic at Fenway Park (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 8, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261128-leafs-beat-bruins-3-1-pastrnak-injured-src1', 'bd-20261128-leafs-beat-bruins-3-1-pastrnak-injured', 'Bruins Lose Captain, Fall to Maple Leafs on Black Friday', 'https://bostonhockeynow.com/2026-11-27-boston-bruins-toronto-maple-leafs-game-25-recap/', 'Boston Hockey Now', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-28T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-28. Editor to confirm.', 'newsroom-assistant', '2026-11-28T11:00:00.000Z');
