INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-texas-beats-texas-am-16-6-sec-title', 'texas-beats-texas-am-16-6-kyle-field-longhorns-sec-championship-georgia-december-5', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Texas beats Texas A&M 16-6 at Kyle Field and books an SEC title game date with Georgia', 'Arch Manning threw for a season-low 143 yards, but the Longhorns defense held the Aggies without a touchdown on Friday, Nov. 27, the Associated Press reported.', 'Texas won a defensive struggle at Texas A&M 16-6 on Friday, Nov. 27, clinching a spot in the SEC Championship Game, according to the Associated Press recap published by ESPN.

Arch Manning completed 18 of 34 passes for a season-low 143 yards, but his 3-yard touchdown pass to Cam Coleman was the only touchdown of the night, the AP reported. Kicker Gianni Spetic made three field goals, including a 54-yarder and a 42-yarder that pushed the lead to 16-6 with about five minutes left. Tawfiq Byard sealed it with an interception in the end zone.

Texas A&M quarterback Brady Hart threw for 201 yards in his second start since Marcel Reed was benched, according to the recap. A crowd of 109,570 watched at Kyle Field in College Station.

## The stakes

Steve Sarkisian''s Longhorns improved to 10-2 and 7-2 in the SEC and will face top-ranked Georgia in Atlanta on Saturday, Dec. 5, the AP reported, keeping their College Football Playoff hopes on track. Mike Elko''s Aggies fell to 4-8 and 1-8 in conference play with their fifth straight loss.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/b/ba/2007_Texas_Longhorns_football_team_entry.jpg', 'The Texas Longhorns take the field before a 2007 game (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 7, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
