INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-ole-miss-wins-egg-bowl-41-17', 'ole-miss-beats-mississippi-state-41-17-egg-bowl-chambliss-dye-seven-sacks', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Ole Miss pulls away from Mississippi State 41-17 for a fourth straight Egg Bowl win', 'The Rebels trailed 10-6 at halftime in Oxford on Friday, Nov. 27, then scored 35 points after the break, Sportsnaut and SEC Country reported.', 'Ole Miss trailed at halftime and then overwhelmed Mississippi State 41-17 in the Egg Bowl at Vaught-Hemingway Stadium in Oxford on Friday, Nov. 27, according to Sportsnaut and SEC Country.

Mississippi State led 10-6 at the break behind a touchdown run from Fluff Bothwell, while the Rebels managed only two Lucas Carneiro field goals, SEC Country reported. Ole Miss outscored the Bulldogs 35-7 in the second half.

## The turning point

After Parker Puckett''s touchdown pass to Bothwell cut the lead to 20-17 in the fourth quarter, Blake Purchase returned a Puckett interception 58 yards to the goal line, and Trinidad Chambliss scored on a 1-yard run with 10:30 left, according to both outlets. Chambliss later added a 21-yard touchdown pass to Michael Smith.

Chambliss threw for 237 yards and two touchdowns and ran for another, SEC Country reported. Joshua Dye ran for 91 yards and two scores. The Ole Miss defense recorded seven sacks and 13 tackles for loss. Bothwell finished with 129 rushing yards for Mississippi State.

## Where they finish

Ole Miss improved to 8-4 and 5-4 in the SEC with its fourth straight win in the rivalry, according to SEC Country. Jeff Lebby''s Mississippi State finished 5-7 and 2-7 and will not be bowl eligible.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/0/04/Lyceum_Building_University_of_Mississippi_LOC_HABS_572258.jpg', 'The Lyceum at the University of Mississippi in Oxford, from the Historic American Buildings Survey, Library of Congress (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 6, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
