INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261128-rivalry-friday-scores-florida-fsu', 'college-football-rivalry-friday-scores-florida-beats-florida-state-26-10-iowa-nebraska-wisconsin-minnesota', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Rivalry Friday scores: Florida wins at Florida State 26-10; Iowa and Wisconsin roll', 'Final scores from college football games played on Friday, Nov. 27, as listed by College Football Pass.', 'Florida went into Tallahassee and beat Florida State 26-10 on Friday, Nov. 27, one of a dozen college football games played on the Friday after Thanksgiving, according to the scoreboard compiled by College Football Pass.

## Big Ten

Iowa beat Nebraska 31-7 at home, and Wisconsin beat Minnesota 28-5 in Madison, according to the listing.

## Around the country

- Toledo won at Ohio 34-31.
- Temple won at Memphis 35-31.
- UTSA beat Tulsa 28-22.
- South Alabama beat Appalachian State 20-13.
- New Mexico beat Air Force 42-19.
- Buffalo won at Akron 17-9.
- North Dakota State won at San Jose State 38-31.

The Texas-Texas A&M and Ole Miss-Mississippi State results are covered in separate Boston Daily stories. Scores are as listed by the source; editors should confirm against official conference results before publishing.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Florida_State_University_versus_the_University_of_Miami_at_Doak_Campbell_Stadium-_Tallahassee,_Florida.jpg', 'Florida State plays Miami at Doak Campbell Stadium in Tallahassee, Florida (file photo). Via Wikimedia Commons; editor to confirm the photographer and license on the file page', 'licensed', 'newsroom', 'content/2026-11-28.sql', 5, 0, 'newsroom-assistant', '2026-11-28T11:00:00.000Z', '2026-11-28T11:00:00.000Z');
